WITH with_latest AS (SELECT s.id, s.product_name, s.category, s.price, s.stock_qty, s.supplier_id, top1.inventory_last_restock, top1.inventory_quantity FROM products s LEFT JOIN LATERAL (SELECT c.last_restock AS inventory_last_restock, c.quantity AS inventory_quantity FROM inventory c WHERE c.product_id = s.id ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT DATE_TRUNC('QUARTER', inventory_last_restock) AS quarter_start, CASE WHEN price >= 1270 THEN 'PREMIUM' ELSE 'STANDARD' END AS price_tier, COUNT(CASE WHEN category = 'Books' THEN 1 END) AS books_count, ROUND(AVG(stock_qty), 2) AS avg_stock_qty, APPROX_PERCENTILE(inventory_quantity, 0.95) AS inventory_quantity_p95, GROUPING(DATE_TRUNC('QUARTER', inventory_last_restock)) AS grouping_id FROM with_latest GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', inventory_last_restock), CASE WHEN price >= 1270 THEN 'PREMIUM' ELSE 'STANDARD' END), (DATE_TRUNC('QUARTER', inventory_last_restock))) ORDER BY books_count NULLS FIRST
